solution.python:
def pipeline(data, *transforms):
    for item in data:
        result = item
        for transform in transforms:
            result = transform(result)
        yield result

def take(gen, n):
    result = []
    for i, item in enumerate(gen):
        if i >= n:
            break
        result.append(item)
    return result

def chain(*generators):
    for gen in generators:
        yield from gen

solution.javascript:
function* pipeline(data, ...transforms) {
  for (const item of data) {
    let result = item;
    for (const transform of transforms) {
      result = transform(result);
    }
    yield result;
  }
}

function take(gen, n) {
  const result = [];
  let count = 0;
  for (const item of gen) {
    if (count >= n) break;
    result.push(item);
    count++;
  }
  return result;
}

function* chain(...generators) {
  for (const gen of generators) {
    yield* gen;
  }
}
